// ==========================================================================
// AUTOMATED COMPONENT DISCOVERY SYSTEM
// ==========================================================================
// Automatically discovers all component pages and generates mappings
// No more manual maintenance when adding new components!

// ==========================================================================
// AUTOMATIC COMPONENT DISCOVERY
// ==========================================================================

/**
 * Automatically discover all component meta files using Vite's import.meta.glob
 * This replaces the manual COMPONENT_REGISTRY array
 */
const componentMetaFiles = import.meta.glob('../../Pages/Documentation/UiComponents/*/meta.js', { 
  eager: true,
  import: 'default'
});

// Also discover custom-demo components
const customDemoMetaFiles = import.meta.glob('../../custom-demo/*/meta.js', {
  eager: true,
  import: 'default'
});

// Merge both sets of meta files
const allMetaFiles = { ...componentMetaFiles, ...customDemoMetaFiles };

/**
 * Generate component registry automatically from discovered meta files
 * This creates the same structure as the old COMPONENT_REGISTRY but dynamically
 */
export const COMPONENT_REGISTRY = Object.entries(allMetaFiles).map(([path, meta]) => {
  // Extract folder name from path
  // For UiComponents: "../../Pages/Documentation/UiComponents/ButtonPage/meta.js" -> "ButtonPage"
  // For custom-demo: "../../custom-demo/UlsUserCardPage/meta.js" -> "UlsUserCardPage"
  const folderName = path.split('/').slice(-2, -1)[0];
  
  return {
    name: meta.menuItem, // Use the menuItem from meta.js as the component name
    folder: folderName
  };
});

/**
 * Automatically generate folder name mappings from discovered components
 * This replaces the manual FOLDER_NAME_MAP object
 */
export const FOLDER_NAME_MAP = Object.fromEntries(
  COMPONENT_REGISTRY.map(({ name, folder }) => [name, folder])
);

/**
 * Automatically generate lowercase folder mappings from discovered components
 * This replaces the manual LOWERCASE_FOLDER_MAP object
 */
export const LOWERCASE_FOLDER_MAP = Object.fromEntries(
  COMPONENT_REGISTRY.map(({ name, folder }) => [name.toLowerCase(), folder])
);

/**
 * Get folder name from PascalCase component name (used by registry.js)
 * @param {string} componentName - PascalCase component name (e.g., "InputNumber")
 * @returns {string} Folder name (e.g., "InputNumPage")
 */
export function getFolderName(componentName) {
  return FOLDER_NAME_MAP[componentName] || `${componentName}Page`;
}

/**
 * Get folder name from lowercase component name (used by DocPageWrapper)
 * @param {string} componentName - Lowercase component name (e.g., "inputnumber")
 * @returns {string} Folder name (e.g., "InputNumPage")
 */
export function getFolderNameFromLowercase(componentName) {
  return LOWERCASE_FOLDER_MAP[componentName] || `${componentName.charAt(0).toUpperCase() + componentName.slice(1)}Page`;
}

// ==========================================================================
// DYNAMIC IMPORT UTILITIES
// ==========================================================================
// All folder-related import logic moved here for centralized management

/**
 * Generate dynamic import path for component page
 * @param {string} componentName - PascalCase component name (e.g., "InputNumber")
 * @returns {string} Dynamic import path
 */
export function getComponentPageImportPath(componentName) {
  const folderName = getFolderName(componentName);
  return `../../Pages/Documentation/UiComponents/${folderName}/index`;
}

/**
 * Generate dynamic import path for component meta file
 * @param {string} componentName - PascalCase component name (e.g., "InputNumber")
 * @returns {string} Dynamic import path
 */
export function getComponentMetaImportPath(componentName) {
  const folderName = getFolderName(componentName);
  return `../../Pages/Documentation/UiComponents/${folderName}/meta`;
}

/**
 * Generate dynamic import path for DocPageWrapper meta file
 * @param {string} componentName - Lowercase component name (e.g., "inputnumber")
 * @returns {string} Dynamic import path
 */
export function getDocPageWrapperMetaPath(componentName) {
  const folderName = getFolderNameFromLowercase(componentName);
  return `/src/Pages/Documentation/UiComponents/${folderName}/meta`;
}

/**
 * Create dynamic import function for component page
 * @param {string} componentName - PascalCase component name (e.g., "InputNumber")
 * @returns {Function} Dynamic import function
 */
export function createComponentPageImport(componentName) {
  const folderName = getFolderName(componentName);
  
  // Check if it's a custom-demo component
  const customDemoPath = `../../custom-demo/${folderName}/index`;
  const standardPath = `../../Pages/Documentation/UiComponents/${folderName}/index`;
  
  // Try custom-demo first, then fall back to standard
  return () => {
    // Try custom-demo path first
    return import(/* @vite-ignore */ customDemoPath).catch(() => {
      // Fall back to standard path
      return import(/* @vite-ignore */ standardPath);
    });
  };
}

/**
 * Create dynamic import function for component meta
 * @param {string} componentName - PascalCase component name (e.g., "InputNumber")
 * @returns {Function} Dynamic import function
 */
export function createComponentMetaImport(componentName) {
  const path = getComponentMetaImportPath(componentName);
  return () => import(/* @vite-ignore */ path);
}

// ==========================================================================
// DEBUGGING UTILITIES
// ==========================================================================

/**
 * Debug utility to see what components were discovered
 * Use this in development to verify the auto-discovery is working
 */
export function debugDiscoveredComponents() {
  console.log('🔍 Auto-discovered components:');
  console.log('COMPONENT_REGISTRY:', COMPONENT_REGISTRY);
  console.log('FOLDER_NAME_MAP:', FOLDER_NAME_MAP);
  console.log('LOWERCASE_FOLDER_MAP:', LOWERCASE_FOLDER_MAP);
  console.log('Total components found:', COMPONENT_REGISTRY.length);
  
  return {
    registry: COMPONENT_REGISTRY,
    folderMap: FOLDER_NAME_MAP,
    lowercaseMap: LOWERCASE_FOLDER_MAP,
    count: COMPONENT_REGISTRY.length
  };
}
